  function warningMessage(w){var map={constraintContradiction:['同时记录了存在约束和没有相关约束，请回看是否矛盾。','Both constraints and no relevant constraints are recorded. Review the apparent contradiction.'],questionsCount:['建议尝试提出 5 个问题（附录 II 为 3 个）。','Consider 5 questions (Appendix II uses 3).'],questionForm:['教材建议将伦理问题写成问句。','Consider phrasing the issue as a question.'],coreCount:['建议聚焦 2 个问题（附录 II 为 1 个）。','Consider 2 focal issues (Appendix II uses 1).'],focusBasis:['为核心问题补一句选择理由。','Add a reason for your focus.'],gapCount:['建议记录至少 2 项缺失信息。','Consider at least 2 information gaps.'],assumptionBasis:['这条假设还没有完整记录依据与推断理由。','This assumption needs supporting material and an inference reason.'],conceptCount:['本组建议澄清 2 个关键词。','The team suggests clarifying 2 key terms.'],conceptColumns:['补充他人理解和本组用法。','Add both interpretations of the term.'],principleCount:['本组建议比较约 3 项相关原则；不需要凑数。','The team suggests examining about 3 relevant principles; no need to pad the list.'],conflictFields:['这项冲突还缺少行动、取舍或理由。','This conflict needs actions, priority, and reasoning.'],reviewNeeded:['部分前序记录尚未复核。','Some earlier entries have not been reviewed.'],answerNeeded:['核心问题还缺少回答或简短论证。','A core question still needs an answer or justification.'],constraintFields:['约束还缺少可行选择或责任判断。','A constraint still needs alternatives or responsibility reasoning.'],preventionCount:['教材练习建议提出至少 3 项预防思路。','The exercise suggests at least 3 preventive ideas.'],emptyStep:['这里还没有记录。可以继续，也可以稍后返回。','No records here yet. Continue or return later.'],linkWhy:['为这条关联补充为什么相关。','Explain why this connection matters.']};if(w.key&&w.key.indexOf('factCount:')===0)return bi('本组建议为「'+t(w.key.split(':')[1])+'」关联约 2 条事实。','The team suggests about 2 relevant facts for '+t(w.key.split(':')[1])+'.');return map[w.key]?map[w.key][locale==='zh'?0:1]:w.message||w.text||w.key;}
