  function rail(step){var own=rows().some(function(x){return x.step===step&&!!(x.text||x.word);})||(step===2&&rows('Q').some(function(x){return x.focusReason;}))||(step===7&&rows().some(function(x){return x.review||(x.checkedIds||[]).length;}));return '<aside class="context-rail"><section class="guide-card"><span class="eyebrow">'+icon('spark')+esc(t('guide'))+'</span><p>'+esc(locale==='zh'?['谁可能受到直接或间接的影响？','为什么这个问题值得深入讨论？','什么事实可能改变你对核心问题的回答？','这项推断为什么合理，而不仅仅是方便？','另一位读者会怎样理解这个词？','哪些原则在这个具体情境中发生冲突？','你遗漏了什么，又缺少了谁的视角？','你的回答对应最初提出的问题吗？','当时还有什么可行行动？','哪些更早的行动可能避免这个困境？'][step-1]:I.prompts[step-1])+'</p>'+tag('team','muted')+'</section><section class="rail-materials"><div class="section-heading"><h3>'+esc(t('library'))+'</h3>'+icon('book')+'</div>'+['timeline','facts','principles','sources'].map(function(tab){return '<button class="material-link" data-action="materials" data-tab="'+tab+'"><span>'+esc(t(tab))+'</span>'+icon('arrow')+'</button>';}).join('')+'<div class="material-status"><span class="status-dot"></span>'+esc(t('materialPending'))+'</div></section><section class="reference-card"><h3>'+esc(t('reference'))+'</h3><p>'+esc(t('referenceLocked'))+'</p>'+button('reference','reference','small quiet','book',(!own||!data.steps[step-1].referenceLevel3?'disabled':'')+' title="'+esc(t('referenceLocked'))+'"')+'</section><div class="rail-note"><span>01—10</span><p>'+esc(t('yourReason'))+'</p></div></aside>';}
  function overview(){var s=state(),qs=rows('Q');return '<section class="view-heading"><span class="eyebrow">FIELDNOTES / '+esc(t('outline'))+'</span><h1>'+esc(t('connect'))+'</h1><p>'+esc(t('overviewSub'))+'</p></section>'+(qs.length?qs.map(function(q){var links=s.relations.filter(function(r){return r.to===q.id&&r.kind==='fact-supports-question';});var gaps=links.map(function(r){return r.from;});var assumptions=rows('A').filter(function(a){return s.relations.some(function(r){return r.from===a.id&&gaps.includes(r.to);});});var p=rows('PA').filter(function(x){return (x.appliesTo||[]).includes(q.id);});var res=s.relations.filter(function(r){return r.to===q.id&&r.kind==='resolution-answers-question';}).map(function(r){return s.items[r.from];});function stack(records){return records.length?records.map(function(x){return '<button class="map-entry" data-action="navigate" data-step="'+(x.step||3)+'" data-id="'+esc(x.id)+'"><span class="record-id">'+esc(x.id)+'</span><p>'+esc(display(x)||'—')+'</p></button>';}).join(''):'<div class="map-empty">—</div>';}
      return '<article class="map-question"><div class="card-head">'+tag(q.isCore?'focus':'question',q.isCore?'green':'muted')+'<span class="record-id">'+esc(q.id)+'</span></div><h2>'+esc(q.text||'—')+'</h2><div class="reasoning-columns"><section><h3>'+esc(t('facts'))+' / '+esc(t('missing'))+'</h3>'+stack(links.map(function(r){var x=s.items[r.from]||data.facts.find(function(f){return f.id===r.from;});return Object.assign({},x,{text:x&&isPending(x.text)?t('noData'):x?x.text:r.from});}))+links.map(function(r){return '<p class="link-reason">'+esc(r.why)+'</p>';}).join('')+'</section><section><h3>'+esc(t('assumptions'))+'</h3>'+stack(assumptions)+'</section><section><h3>'+esc(t('principles'))+'</h3>'+stack(p)+'</section><section><h3>'+esc(t('conclusion'))+'</h3>'+stack(res.filter(Boolean))+'</section></div></article>';}).join(''):empty('overviewEmpty','emptySub'))+'<section class="global-concepts"><h3>'+esc(t('concepts'))+'</h3>'+rows('C').map(function(c){return '<div class="concept-summary"><strong>'+esc(c.word)+'</strong><p>'+esc(c.mine||c.myUsage||'—')+'</p></div>';}).join('')+'</section>';}
  function comparable(value){var copy=JSON.parse(JSON.stringify(value||{}));delete copy.createdAt;delete copy.updatedAt;delete copy.review;return copy;}
  function snapshotChanges(a,b){var result=[];['items','relations','conflicts'].forEach(function(kind){var x=kind==='items'?a.items:Object.fromEntries((a[kind]||[]).map(function(r){return[r.id,r];})),y=kind==='items'?b.items:Object.fromEntries((b[kind]||[]).map(function(r){return[r.id,r];}));new Set(Object.keys(x||{}).concat(Object.keys(y||{}))).forEach(function(id){if(JSON.stringify(comparable(x[id]))!==JSON.stringify(comparable(y[id])))result.push({id:id,before:x[id],after:y[id],kind:!x[id]?'added':!y[id]?'deleted':'modified'});});});return result;}
  function snapshotText(x){
    if(!x)return '—';
    var aliases={word:'word',others:'others',othersView:'others',mine:'mine',myUsage:'mine',focusReason:'focusWhy',why:'whyRelated',reason:'reason',supportsA:'supportsA',supportsB:'supportsB',priority:'coordinate',mitigationJudgment:'mitigation',alternatives:'alternatives',order:'priority',from:'from',to:'to',kind:'associationKind',scope:'scope'};
    var values=[];
    if(x.principleId)values.push(principleName(x.principleId));
    if(x.text)values.push(x.text);
    Object.keys(aliases).forEach(function(k){if(x[k]&&!((k==='othersView'&&x.others!==undefined)||(k==='myUsage'&&x.mine!==undefined)))values.push(t(aliases[k])+': '+(k==='scope'?t(x[k]==='case'?'caseScope':'generalScope'):x[k]));});
    ['actors','basisRefs','appliesTo'].forEach(function(k){if(x[k]&&x[k].length)values.push(t(k==='actors'?'actor':k==='basisRefs'?'basis':'questionTarget')+': '+x[k].join(' · '));});
    if(x.isCore!==undefined)values.push(t('core')+': '+bi(x.isCore?'是':'否',x.isCore?'Yes':'No'));
    return values.join('\n\n')||x.id||'—';
  }
  function discussionSummary(){var a=state().authorship;return '<section class="discussion-summary"><h3>'+esc(t('notes'))+'</h3><div class="two-columns"><div><span class="section-label">'+esc(t('discussion'))+'</span>'+a.notes.map(function(n){return '<p>'+esc(n)+'</p>';}).join('')+'</div><div><span class="section-label">'+esc(t('reservation'))+'</span>'+a.reservations.map(function(n){return '<p>'+esc(n)+'</p>';}).join('')+'</div></div></section>';}
  function revisions(){var s=state(),a=s.snapshots.find(function(x){return x.id==='SN-01';}),b=s.snapshots.find(function(x){return x.id==='SN-02';});var changes=a&&b?snapshotChanges(a.payload,b.payload):[];return '<section class="view-heading"><span class="eyebrow">FIELDNOTES / '+esc(t('revisions'))+'</span><h1>'+esc(t('snapshotEmpty'))+'</h1><p>'+esc(t('snapshotSub'))+'</p></section><div class="snapshot-grid">'+[a,b].map(function(sn,idx){return '<article class="snapshot-card"><span class="eyebrow">0'+(idx+1)+' / '+esc(t(idx?'revised':'initial'))+'</span><h2>'+esc(t(idx?'revised':'initial'))+'</h2><p>'+(sn?esc(new Date(sn.createdAt).toLocaleString(locale==='zh'?'zh-CN':'en-GB')):esc(t('empty')))+'</p>'+(presentation?'':button(idx?'secondSnapshot':'firstSnapshot','snapshot','small primary','history','data-slot="'+(idx?'reviewed':'initial')+'"'))+(sn&&!presentation?button('restore','restore','small quiet',null,'data-id="'+sn.id+'"'):'')+'</article>';}).join('')+'</div>'+(a&&b?'<div class="section-heading"><h3>'+changes.length+' '+esc(t('changeCount'))+'</h3></div>'+(changes.length?changes.map(function(c){return '<article class="diff-card"><div class="card-head">'+tag(c.kind,c.kind==='added'?'green':'muted')+'<span class="record-id">'+esc(c.id)+'</span></div><div class="two-columns"><section><h3>'+esc(t('before'))+'</h3><pre>'+esc(snapshotText(c.before))+'</pre></section><section><h3>'+esc(t('after'))+'</h3><pre>'+esc(snapshotText(c.after))+'</pre></section></div></article>';}).join(''):'<p class="notice">'+esc(t('noChanges'))+'</p>'):empty('snapshotEmpty','snapshotSub'))+discussionSummary();}
