    if(action==='language'){locale=el.dataset.lang;try{localStorage.setItem('fieldnotes.ui.language',locale);}catch(e){}render();if(modal.open)modal.close();}
    if(action==='add'){dispatch('ADD_ITEM',{type:el.dataset.type,step:Number(el.dataset.step),fields:el.dataset.type==='C'?{word:'',others:'',mine:''}:el.dataset.type==='PA'?{order:rows('PA').length+1}:undefined});var items=rows(el.dataset.type),last=items[items.length-1];setTimeout(function(){var input=document.querySelector('[data-item="'+last.id+'"]');if(input)input.focus();},0);}
    if(action==='delete'){var it=state().items[el.dataset.id];var dependencies=engine.affected?engine.affected(it.id):[];var impacts=Array.from(new Set(dependencies.map(function(id){return state().items[id]?state().items[id].step:null;}).filter(Boolean)));confirmAction(t((state().relations.some(function(r){return r.from===it.id||r.to===it.id;})||(engine.affected&&engine.affected(it.id).length))?'deleteLinked':'deleteConfirm')+(impacts.length?' '+t('step')+' '+impacts.join(', '):''),function(){dispatch('DELETE_ITEM',{id:it.id});});}
    if(action==='delete-conflict')confirmAction(t('deleteConfirm'),function(){dispatch('DELETE_CONFLICT',{id:el.dataset.id});});
    if(action==='close'){modal.close();modal.confirmHandler=null;}
    if(action==='confirm'){var fn=modal.confirmHandler;modal.close();modal.confirmHandler=null;if(fn)fn();}
    if(action==='materials')openMaterials(el.dataset.tab);
    if(action==='material-tab')modalContent.innerHTML='<div class="modal-head"><h2>'+esc(t('materials'))+'</h2>'+button('close','close','icon-button quiet','close')+'</div>'+materialBody(el.dataset.tab);
    if(action==='link') {if(modal.open)modal.close();linkDialog(el.dataset.id);}
    if(action==='unlink')dispatch('UNLINK',{id:el.dataset.id});
    if(action==='basis')basisDialog(el.dataset.id);
    if(action==='concept')dispatch('ADD_ITEM',{type:'C',step:5,fields:{word:el.dataset.word,others:'',mine:''}});
    if(action==='constraint')dispatch('ADD_ITEM',{type:'RC',step:9,fields:{text:el.dataset.text}});
    if(action==='no-constraints')dispatch('ADD_ITEM',{type:'RC',step:9,fields:{checkedIds:['none'],text:''}});
    if(action==='principle'){dispatch('ADD_ITEM',{type:'PA',step:6,fields:{principleId:el.dataset.id,appliesTo:[],order:rows('PA').length+1}});modal.close();view='workbook';dispatch('NAVIGATE',{step:6});}
    if(action==='rank'){var list=rows('PA').sort(function(a,b){return(a.order||0)-(b.order||0);}),idx=list.findIndex(function(x){return x.id===el.dataset.id;}),dest=idx+Number(el.dataset.direction);if(dest>=0&&dest<list.length){var other=list[dest];list[dest]=list[idx];list[idx]=other;list.forEach(function(x,i){dispatch('UPDATE_ITEM',{id:x.id,fields:{order:i+1}});});}}
