    if(action==='answer')dispatch('ANSWER',{question:el.dataset.id});
    if(action==='snapshot'){var slot=el.dataset.slot,id=slot==='initial'?'SN-01':'SN-02';var save=function(){engine.createSnapshot(slot);toast(t('snapshotSaved'));};if(state().snapshots.some(function(x){return x.id===id;}))confirmAction(t('snapshotReplace'),save);else save();}
    if(action==='restore')confirmAction(t('restoreConfirm'),function(){engine.restoreSnapshot(el.dataset.id);});
    if(action==='reference'){if(presentation)return;dispatch('ACCEPT_L3',{step:current()});var ref=data.steps[current()-1].referenceLevel3;openDialog('reference','<p class="notice">'+esc(t('referenceDisclaimer'))+'</p>'+tag('textbook')+'<p>'+esc(!ref||isPending(ref.body)?t('referencePending'):ref.body)+'</p><small>'+esc(t('methodBasis'))+' · '+esc(data.meta.builtAt)+'</small>',true);}
    if(action==='revision-note')openDialog('changeReason','<form id="revision-form" data-id="'+esc(el.dataset.id)+'"><label class="field"><span>'+esc(t('changeReason'))+'</span><textarea name="text" required></textarea></label><div class="modal-actions">'+button('cancel','close','quiet')+'<button type="submit" class="button primary">'+esc(t('save'))+'</button></div></form>');
    if(action==='notes')openDialog('notes','<form id="notes-form"><label class="field"><span>'+esc(t('author'))+'</span><input name="author" placeholder="'+esc(t('authorHint'))+'"></label><label class="field"><span>'+esc(t('notes'))+'</span><textarea name="text" placeholder="'+esc(t('noteHint'))+'" required></textarea></label><label class="field"><select name="kind"><option value="note">'+esc(t('discussion'))+'</option><option value="reservation">'+esc(t('reservation'))+'</option></select></label><button type="submit" class="button primary" '+(presentation?'disabled':'')+'>'+esc(t('addNote'))+'</button></form><div class="discussion-list">'+state().authorship.notes.concat(state().authorship.reservations).map(function(n){return '<p>'+esc(n)+'</p>';}).join('')+'</div>');
    if(action==='export')exportDialog();
    if(action==='download-json'){download(engine.exportProject(),'fukushima-project.json','application/json');modal.close();}
    if(action==='download-md'){download(exportMarkdown(),'fukushima-notes.md','text/markdown;charset=utf-8');modal.close();}
