  window.FIELDNOTES={mount:function(runtime){engine=runtime;workingEngine=runtime;presentation=null;mockMode=false;bindEngine();render();},getEngine:function(){return engine;},getLocale:function(){return locale;},snapshotChanges:snapshotChanges};
